package com.eventpulse.service;
import com.eventpulse.model.*;import com.eventpulse.repository.*;import java.util.*;import org.junit.jupiter.api.Test;import software.amazon.awssdk.core.exception.SdkClientException;import software.amazon.awssdk.services.sesv2.SesV2Client;import software.amazon.awssdk.services.sesv2.model.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class NotificationServiceTest {
 private UserProfile user(){var u=new UserProfile();u.setEmail("user@example.test");return u;}
 @Test void storesSesAcceptanceAndMessageId(){var ses=mock(SesV2Client.class);var nr=mock(NotificationRepository.class);var ur=mock(UserRepository.class);when(ur.findById("u")).thenReturn(Optional.of(user()));when(nr.claim(any())).thenReturn(true);when(nr.findById(any())).thenReturn(Optional.empty());when(ses.sendEmail(any(SendEmailRequest.class))).thenReturn(SendEmailResponse.builder().messageId("m-1").build());when(nr.save(any())).thenAnswer(i->i.getArgument(0));var result=new NotificationService(ses,"sender@example.test","events",nr,mock(RegistrationRepository.class),ur).sendToUser("u","e",NotificationService.EVENT_REMINDER,"Subject","Body");assertEquals("ACCEPTED_BY_SES",result.getStatus());assertEquals("m-1",result.getMessageId());verify(ses).sendEmail(any(SendEmailRequest.class));}
 @Test void definitivelyRejectedNotificationCanRetryWithSameId(){var ses=mock(SesV2Client.class);var nr=mock(NotificationRepository.class);var ur=mock(UserRepository.class);when(ur.findById("u")).thenReturn(Optional.of(user()));when(nr.findById(any())).thenReturn(Optional.empty());when(nr.claim(any())).thenReturn(true);when(nr.save(any())).thenAnswer(i->i.getArgument(0));when(ses.sendEmail(any(SendEmailRequest.class))).thenThrow(SesV2Exception.builder().statusCode(400).message("rejected").build()).thenReturn(SendEmailResponse.builder().messageId("m-2").build());var service=new NotificationService(ses,"sender@example.test",null,nr,mock(RegistrationRepository.class),ur);var failed=service.sendToUser("u","e",NotificationService.EVENT_ANNOUNCEMENT,"s","b","revision:1");var accepted=service.sendToUser("u","e",NotificationService.EVENT_ANNOUNCEMENT,"s","b","revision:1");assertEquals("FAILED",failed.getStatus());assertEquals("ACCEPTED_BY_SES",accepted.getStatus());assertEquals(failed.getNotificationId(),accepted.getNotificationId());verify(nr,times(2)).claim(any());verify(ses,times(2)).sendEmail(any(SendEmailRequest.class));}
 @Test void ambiguousSesResultIsNotResent(){var ses=mock(SesV2Client.class);var nr=mock(NotificationRepository.class);var ur=mock(UserRepository.class);when(ur.findById("u")).thenReturn(Optional.of(user()));var stored=new HashMap<String,NotificationRecord>();when(nr.findById(any())).thenAnswer(i->Optional.ofNullable(stored.get(i.getArgument(0))));when(nr.claim(any())).thenAnswer(i->{var r=(NotificationRecord)i.getArgument(0);stored.put(r.getNotificationId(),r);return true;});when(nr.save(any())).thenAnswer(i->{var r=(NotificationRecord)i.getArgument(0);stored.put(r.getNotificationId(),r);return r;});when(ses.sendEmail(any(SendEmailRequest.class))).thenThrow(SdkClientException.builder().message("connection lost").build());var service=new NotificationService(ses,"sender@example.test",null,nr,mock(RegistrationRepository.class),ur);var first=service.sendToUser("u","e",NotificationService.EVENT_REMINDER,"s","b","reminder:1h");var replay=service.sendToUser("u","e",NotificationService.EVENT_REMINDER,"s","b","reminder:1h");assertEquals("UNKNOWN",first.getStatus());assertSame(first,replay);verify(ses,times(1)).sendEmail(any(SendEmailRequest.class));}
 @Test void missingEmailIsRecordedAsRetryableFailure(){var nr=mock(NotificationRepository.class);when(nr.claim(any())).thenReturn(true);when(nr.findById(any())).thenReturn(Optional.empty());when(nr.save(any())).thenAnswer(i->i.getArgument(0));var ses=mock(SesV2Client.class);var result=new NotificationService(ses,"sender@example.test",null,nr,mock(RegistrationRepository.class),mock(UserRepository.class)).sendToUser("u","e",NotificationService.EVENT_REMINDER,"s","b");assertEquals("FAILED",result.getStatus());verifyNoInteractions(ses);}
}
